  1→/* ==========================================================================
  2→   App Shell Layout - CSS Grid System
  3→   ========================================================================== */
  4→
  5→/* ==========================================================================
  6→   Matrix Background Canvas
  7→   ========================================================================== */
  8→
  9→.matrix-canvas {
 10→  position: fixed;
 11→  top: 0;
 12→  left: 0;
 13→  width: 100%;
 14→  height: 100%;
 15→  z-index: -1;
 16→}
 17→
 18→/* ==========================================================================
 19→   App Shell Grid Container
 20→   ========================================================================== */
 21→
 22→.app-shell {
 23→  display: grid;
 24→  grid-template-rows: auto auto 1fr auto;
 25→  grid-template-columns: 180px 1fr;
 26→  grid-template-areas:
 27→    'header header'
 28→    'banner banner'
 29→    'sidebar main'
 30→    'footer footer';
 31→  height: 100vh;
 32→  overflow: hidden;
 33→  position: relative;
 34→}
 35→
 36→/* ==========================================================================
 37→   Header
 38→   ========================================================================== */
 39→
 40→.app-header {
 41→  grid-area: header;
 42→  display: flex;
 43→  justify-content: space-between;
 44→  align-items: center;
 45→  padding: 12px 24px;
 46→  background-color: rgb(0 0 0 / 50%);
 47→  border-bottom: 1px solid var(--color-border-dim);
 48→  position: relative;
 49→  z-index: 2;
 50→}
 51→
 52→.header-left {
 53→  display: flex;
 54→  align-items: center;
 55→  gap: 8px;
 56→}
 57→
 58→.header-prompt {
 59→  font-size: 20px;
 60→  font-weight: var(--font-weight-bold);
 61→  color: var(--color-text-primary);
 62→}
 63→
 64→.header-logo {
 65→  font-size: 14px;
 66→  font-weight: var(--font-weight-semibold);
 67→  color: var(--color-text-primary);
 68→  letter-spacing: 1px;
 69→}
 70→
 71→.header-right {
 72→  display: flex;
 73→  align-items: center;
 74→  gap: 8px;
 75→}
 76→
 77→/* Search button */
 78→.header-search-btn {
 79→  background: none;
 80→  border: 1px solid var(--color-border-dim);
 81→  color: var(--color-text-secondary);
 82→  font-family: var(--font-family-mono);
 83→  font-size: 11px;
 84→  padding: 4px 8px;
 85→  cursor: pointer;
 86→  display: flex;
 87→  align-items: center;
 88→  gap: 4px;
 89→}
 90→
 91→.header-search-btn:hover {
 92→  color: var(--color-green-primary);
 93→  border-color: var(--color-green-primary);
 94→}
 95→
 96→.header-search-btn:focus-visible {
 97→  outline: 1px solid var(--color-green-primary);
 98→  outline-offset: 1px;
 99→}
100→
101→.header-search-btn kbd {
102→  font-family: var(--font-family-mono);
103→  font-size: 10px;
104→  border: 1px solid currentcolor;
105→  padding: 0 3px;
106→  border-radius: 2px;
107→}
108→
109→/* ==========================================================================
110→   Sidebar
111→   ========================================================================== */
112→
113→.app-sidebar {
114→  grid-area: sidebar;
115→  display: flex;
116→  flex-direction: column;
117→  justify-content: space-between;
118→  background-color: rgb(0 0 0 / 50%);
119→  border-right: 1px solid var(--color-border-dim);
120→  overflow-y: auto;
121→  position: relative;
122→  z-index: 1;
123→}
124→
125→.sidebar-nav {
126→  padding: 16px;
127→  display: flex;
128→  flex-direction: column;
129→  gap: 4px;
130→}
131→
132→.sidebar-footer {
133→  padding: 16px;
134→}
135→
136→/* Nav Item */
137→.nav-item {
138→  display: flex;
139→  align-items: center;
140→  gap: 12px;
141→  padding: 8px 12px;
142→  font-size: 12px;
143→  font-weight: var(--font-weight-normal);
144→  color: var(--color-text-secondary);
145→  text-decoration: none;
146→  border-radius: 0;
147→  transition: background-color 0.15s ease, color 0.15s ease;
148→}
149→
150→.nav-item:hover {
151→  color: var(--color-text-primary);
152→  text-decoration: none;
153→}
154→
155→.nav-item--active {
156→  background-color: var(--color-nav-active);
157→  color: var(--color-text-primary);
158→  font-weight: var(--font-weight-semibold);
159→}
160→
161→.nav-item-icon {
162→  font-family: var(--font-family-mono);
163→  font-size: 14px;
164→}
165→
166→/* Storage Quota */
167→.storage-quota {
168→  display: flex;
169→  flex-direction: column;
170→  gap: 6px;
171→}
172→
173→.storage-quota-bar {
174→  width: 100%;
175→  height: 6px;
176→  background-color: var(--color-border-dim);
177→  border-radius: 3px;
178→  overflow: hidden;
179→}
180→
181→.storage-quota-fill {
182→  height: 100%;
183→  background-color: var(--color-green-primary);
184→  transition: width 0.3s ease;
185→}
186→
187→.storage-quota-text {
188→  font-size: 10px;
189→  color: var(--color-text-secondary);
190→}
191→
192→/* ==========================================================================
193→   Main Content Area
194→   ========================================================================== */
195→
196→.app-main {
197→  grid-area: main;
198→  overflow-y: auto;
199→  background-color: rgb(0 0 0 / 90%);
200→  position: relative;
201→  z-index: 1;
202→}
203→
204→/* ==========================================================================
205→   Footer
206→   ========================================================================== */
207→
208→.app-footer {
209→  grid-area: footer;
210→  display: flex;
211→  justify-content: space-between;
212→  align-items: center;
213→  padding: 8px 24px;
214→  background-color: rgb(0 0 0 / 50%);
215→  border-top: 1px solid var(--color-border-dim);
216→  position: relative;
217→  z-index: 1;
218→}
219→
220→.footer-left,
221→.footer-center,
222→.footer-right {
223→  display: flex;
224→  align-items: center;
225→}
226→
227→.footer-center {
228→  gap: 16px;
229→}
230→
231→.footer-copyright {
232→  font-size: 9px;
233→  color: var(--color-border-dim);
234→}
235→
236→.footer-link {
237→  font-size: 9px;
238→  color: var(--color-text-secondary);
239→  text-decoration: none;
240→  transition: color 0.15s ease;
241→}
242→
243→.footer-link:hover {
244→  color: var(--color-text-primary);
245→  text-decoration: none;
246→}
247→
248→/* Status Indicator */
249→.status-indicator {
250→  display: flex;
251→  align-items: center;
252→  gap: 6px;
253→  font-size: 10px;
254→  color: var(--color-text-secondary);
255→}
256→
257→.status-indicator-dot {
258→  width: 6px;
259→  height: 6px;
260→  border-radius: 50%;
261→}
262→
263→.status-indicator-dot--connected {
264→  background-color: var(--color-green-primary);
265→  box-shadow: var(--glow-green);
266→}
267→
268→.status-indicator-dot--disconnected {
269→  background-color: var(--color-error);
270→}
271→
272→.status-indicator-dot--loading {
273→  background-color: var(--color-text-secondary);
274→  animation: pulse 1.5s ease-in-out infinite;
275→}
276→
277→@keyframes pulse {
278→  0%, 100% {
279→    opacity: 1;
280→  }
281→  50% {
282→    opacity: 0.4;
283→  }
284→}
285→
286→.status-indicator-text {
287→  font-family: var(--font-family-mono);
288→}
289→
290→/* ==========================================================================
291→   User Menu
292→   ========================================================================== */
293→
294→.user-menu {
295→  position: relative;
296→}
297→
298→.user-menu-trigger {
299→  display: flex;
300→  align-items: center;
301→  gap: 4px;
302→  padding: 4px 8px;
303→  font-size: 11px;
304→  color: var(--color-text-secondary);
305→  cursor: pointer;
306→  transition: color 0.15s ease;
307→  background: none;
308→  border: none;
309→  font-family: var(--font-family-mono);
310→}
311→
312→.user-menu-trigger:hover {
313→  color: var(--color-text-primary);
314→}
315→
316→.user-menu-caret {
317→  font-size: 8px;
318→}
319→
320→.user-menu-dropdown {
321→  position: absolute;
322→  top: calc(100% + 4px);
323→  right: 0;
324→  min-width: 120px;
325→  background-color: var(--color-background);
326→  border: 1px solid var(--color-border-dim);
327→  border-radius: 4px;
328→  padding: 4px 0;
329→  z-index: 100;
330→}
331→
332→/* Invisible bridge covering the gap between trigger and dropdown
333→   so the mouse doesn't leave .user-menu while crossing the 4px gap */
334→.user-menu-dropdown::before {
335→  content: '';
336→  position: absolute;
337→  top: -4px;
338→  left: 0;
339→  right: 0;
340→  height: 4px;
341→}
342→
343→.user-menu-item {
344→  display: block;
345→  width: 100%;
346→  padding: 8px 12px;
347→  font-size: 11px;
348→  font-family: var(--font-family-mono);
349→  color: var(--color-text-secondary);
350→  text-align: left;
351→  text-decoration: none;
352→  background: none;
353→  border: none;
354→  cursor: pointer;
355→  transition: color 0.15s ease, background-color 0.15s ease;
356→}
357→
358→.user-menu-item:hover {
359→  color: var(--color-text-primary);
360→  background-color: var(--color-nav-active);
361→  text-decoration: none;
362→}
363→
364→/* ==========================================================================
365→   Mobile Responsive (768px breakpoint)
366→   ========================================================================== */
367→
368→@media (max-width: 768px) {
369→  .app-shell {
370→    grid-template-columns: 1fr;
371→    grid-template-areas:
372→      'header'
373→      'banner'
374→      'main'
375→      'footer';
376→  }
377→
378→  .app-sidebar {
379→    display: none;
380→  }
381→}
